add_filter( 'woocommerce_new_customer_data', 'perfectpixel_new_customer_role' );

function perfectpixel_new_customer_role( $data ) {
	$role = get_role( sanitize_key( '{{new_customer_role}}' ) );
	// Never hand out roles that can edit content or manage the site.
	if ( $role && ! $role->has_cap( 'edit_posts' ) && ! $role->has_cap( 'manage_woocommerce' ) && ! $role->has_cap( 'manage_options' ) ) {
		$data['role'] = $role->name;
	}
	return $data;
}
